import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.7R1OEGYz.js";const c=JSON.parse('{"title":"Questions and approvals","description":"","frontmatter":{},"headers":[],"relativePath":"questions-approvals.md","filePath":"questions-approvals.md","lastUpdated":1793867713000}'),n={name:"questions-approvals.md"};function r(i,e,h,l,d,u){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="questions-and-approvals" tabindex="-1">Questions and approvals <a class="header-anchor" href="#questions-and-approvals" aria-label="Permalink to &quot;Questions and approvals&quot;">​</a></h1><p>An agent stops and waits for a person in two situations. It <strong>asks a question</strong>: a choice or some free text, such as which of two approaches to take. Or it <strong>asks for permission</strong> to run a tool. This page explains where both appear, who can answer, and how to reduce the interruptions.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> the session owner answers permission requests. A Collaborator on a <a href="/docs/sharing">shared session</a> (Enterprise) can answer questions too, but not permission requests. Members of a linked Telegram group can answer from the chat (see <a href="/docs/chat">Chat</a>).</p><h2 id="questions-from-the-agent" tabindex="-1">Questions from the agent <a class="header-anchor" href="#questions-from-the-agent" aria-label="Permalink to &quot;Questions from the agent&quot;">​</a></h2><p>When Claude Code, Codex or OpenCode asks a question with choices, the Workspace shows it in full, with its options:</p><ul><li>Click an option to answer.</li><li>An option such as <em>Type something</em> opens a text field: write your answer and send it.</li><li>A multi-select question ticks options one by one and moves on with its own step button; at the end, <strong>Submit answers</strong> sends them. OpenCode shows a review of your answers first.</li><li>If the question cannot be shown as buttons, the Workspace says so, and <strong>Open terminal</strong> opens the agent&#39;s console to answer there.</li></ul><p>While a question is open, the session gets a <strong>?</strong> marker in the sidebar, with the question as its tooltip, and its status reads <strong>Question open</strong>. The home page lists it under <strong>Needs you</strong>, and the session list can be filtered by <strong>Question open</strong>. The marker disappears when the question is answered or cancelled, at the end of the turn, when the context is cleared and on a restart. A session that has simply finished its turn and waits for your next message shows <em>The agent is waiting for your reply</em> instead, without a marker.</p><p>A question in a session you can only view does not count as needing you.</p><div class="tip custom-block"><p class="custom-block-title">Not every agent asks this way</p><p>Cursor emits no question events, so its questions appear only in its terminal and get no marker. The marker was checked with Claude Code and Codex; OpenCode uses the same question events.</p></div><h2 id="permission-requests" tabindex="-1">Permission requests <a class="header-anchor" href="#permission-requests" aria-label="Permalink to &quot;Permission requests&quot;">​</a></h2><p>In an Interactive session, a tool the agent wants to run raises a permission request, shown above the conversation with what the agent wants to do:</p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Allow</strong></td><td>Runs the tool this once</td></tr><tr><td><strong>Allow (don&#39;t ask again)</strong></td><td>Runs it and allows that tool for the rest of the session</td></tr><tr><td><strong>Allow everything</strong></td><td>Turns on <a href="/docs/auto-approve">auto approve</a> for the session and answers this request</td></tr><tr><td><strong>Deny</strong></td><td>Refuses the tool; the agent is told and continues</td></tr></tbody></table><p>The same request is sent to your linked <a href="/docs/chat">Telegram, Signal</a> or <a href="/docs/slack">Slack</a> chat, where you can answer it as well. Whichever answer arrives first counts. A request nobody answers expires after its waiting period. The agent CLI then falls back to its own permission prompt: in an Interactive session it asks in its terminal, in an unattended session the tool is not run.</p><p>Where requests are raised depends on the agent:</p><ul><li><strong>Claude Code, Codex and OpenCode</strong> ask AgentHub on every tool call, so switching auto approve on or off takes effect in the running session.</li><li><strong>Cursor</strong> and <strong>OpenClaw</strong> read the auto-approve setting once at start; changing it needs a restart.</li><li><strong>OpenClaw</strong> has no per-call hook: an interactive OpenClaw session asks in its own terminal only, and its requests do not reach the web app&#39;s buttons or the chat.</li></ul><h3 id="requests-that-come-from-agenthub-itself" tabindex="-1">Requests that come from AgentHub itself <a class="header-anchor" href="#requests-that-come-from-agenthub-itself" aria-label="Permalink to &quot;Requests that come from AgentHub itself&quot;">​</a></h3><p>Two other kinds of request appear in the same place:</p><ul><li><strong>Network ports:</strong> <em>The agent asks to open network port …</em> when the agent wants to accept or make a connection on a port that is closed by default. See <a href="/docs/network-ports">Network ports</a>.</li><li><strong>Secrets:</strong> a banner when the agent asks for a secret with <code>secret_request</code>, with a link to the form where you enter the value. See <a href="/docs/secrets#when-an-agent-asks-for-a-secret">Secrets</a>.</li></ul><h3 id="the-account-email-check" tabindex="-1">The account email check <a class="header-anchor" href="#the-account-email-check" aria-label="Permalink to &quot;The account email check&quot;">​</a></h3><p>Claude Code asks before a tool call would send the signed-in account&#39;s email address to the network. In an Interactive session without auto approve, that question is shown in the terminal and you decide. In Autonomous sessions and sessions with auto approve on, AgentHub declines it automatically; auto approve is not treated as consent to share the email address. In permission requests relayed to chat, the detected account email is replaced with <code>[account email]</code>.</p><h2 id="fewer-interruptions" tabindex="-1">Fewer interruptions <a class="header-anchor" href="#fewer-interruptions" aria-label="Permalink to &quot;Fewer interruptions&quot;">​</a></h2><ul><li>Use <strong>Allow (don&#39;t ask again)</strong> for tools you approve over and over.</li><li>For unattended work, give the session an allow list under <strong>Advanced</strong> in the <a href="/docs/sessions#tool-policy-for-unattended-sessions">New session dialog</a>.</li><li>Turn on <a href="/docs/auto-approve">auto approve</a> for a container you would hand over anyway.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/docs/auto-approve">Auto approve</a></li><li><a href="/docs/workspace">Workspace</a></li><li><a href="/docs/chat">Chat: Telegram and Signal</a></li></ul>',24)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
